def has_distinct_nonzero_digits(m):
    """Checks if m consists of distinct, non-zero digits."""
    s = str(m)
    if not s:
        return False
    digits = set()
    for char in s:
        d = int(char)
        if d == 0:
            return False
        if d in digits:
            return False
        digits.add(d)
    return True

